let m = run(initModel, [
PlantCrop(0, 0),
WaterField,
HarvestCrop(0, 0)
]) in
isPlanted(getCell(m.field, 0, 0))
end;

hint "PassDay increments day count"
test
let m = run(initModel, [PassDay, PassDay, PassDay]) in
m.dayCount == 3
